import java.io.*;
import java.util.*;

public class CF884F {
    public static void main(String[] args) {
        new CF884F().start();
    }

    Scanner sc = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out, true);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    void start() {
        solve();
        out.close();
    }

    void solve() {
        int n = sc.nextInt() / 2;
        int totalNodes = 1 + n + ALPHABET_SIZE + 1;

        int[][] adj = new int[totalNodes][];
        int[][] to = new int[totalNodes * ALPHABET_SIZE * 2][];
        int edgeCount = 0;

        // Initialize adjacency lists
        for (int i = 0; i < totalNodes; i++) {
            adj[i] = new int[ALPHABET_SIZE * 2 + 5];
            Arrays.fill(adj[i], -1);
        }

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        // Connect source to positions
        for (int i = 0; i < n; i++) {
            addEdge(adj, to, edgeCount++, 0, 1 + i, 2, 0);
        }

        // Connect positions to letters
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ci = chars[i] - 'a';
            int cj = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == ci && letter == cj) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == ci) {
                    val = values[i];
                } else if (letter == cj) {
                    val = values[j];
                } else {
                    val = 0;
                }
                addEdge(adj, to, edgeCount++, 1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            addEdge(adj, to, edgeCount++, 1 + n + letter, totalNodes - 1, letterCounts[letter], 0);
        }

        int result = minCostMaxFlow(adj, to, edgeCount, totalNodes, 0, totalNodes - 1);
        out.println(-result);
    }

    void addEdge(int[][] adj, int[][] to, int idx, int u, int v, int cap, int cost) {
        int edgeIdx = idx * 2;
        to[edgeIdx] = new int[]{v, cap, cost, adj[u][0]++};
        if (adj[u].length > adj[u][0]) {
            adj[u][adj[u][0]] = edgeIdx;
        }

        edgeIdx++;
        to[edgeIdx] = new int[]{u, 0, -cost, adj[v][0]++};
        if (adj[v].length > adj[v][0]) {
            adj[v][adj[v][0]] = edgeIdx;
        }
    }

    int minCostMaxFlow(int[][] adj, int[][] to, int edgeCount, int totalNodes, int src, int dst) {
        int[] potential = new int[totalNodes];
        Arrays.fill(potential, INF);
        potential[src] = 0;

        // Bellman-Ford for initial potential
        for (int iter = 0; iter < totalNodes; iter++) {
            for (int u = 0; u < totalNodes; u++) {
                if (potential[u] == INF) continue;
                for (int i = 1; i <= adj[u][0]; i++) {
                    int e = adj[u][i];
                    int v = to[e][0], cap = to[e][1], cost = to[e][2];
                    if (cap > 0 && potential[u] + cost < potential[v]) {
                        potential[v] = potential[u] + cost;
                    }
                }
            }
        }

        int totalCost = 0;

        while (true) {
            int[] dist = new int[totalNodes];
            int[] prevNode = new int[totalNodes];
            int[] prevEdge = new int[totalNodes];
            Arrays.fill(dist, INF);
            dist[src] = 0;

            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            pq.offer(new int[]{0, src});
            boolean[] visited = new boolean[totalNodes];

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int d = cur[0], u = cur[1];
                if (visited[u]) continue;
                visited[u] = true;

                for (int i = 1; i <= adj[u][0]; i++) {
                    int e = adj[u][i];
                    int v = to[e][0], cap = to[e][1], cost = to[e][2];
                    if (cap > 0 && dist[u] + cost + potential[u] - potential[v] < dist[v]) {
                        dist[v] = dist[u] + cost + potential[u] - potential[v];
                        prevNode[v] = u;
                        prevEdge[v] = e;
                        pq.offer(new int[]{dist[v], v});
                    }
                }
            }

            if (dist[dst] == INF) break;

            for (int i = 0; i < totalNodes; i++) {
                if (dist[i] < INF) potential[i] += dist[i];
            }

            int f = INF;
            for (int v = dst; v != src; v = prevNode[v]) {
                int e = prevEdge[v];
                f = Math.min(f, to[e][1]);
            }

            for (int v = dst; v != src; v = prevNode[v]) {
                int e = prevEdge[v];
                to[e][1] -= f;
                to[e ^ 1][1] += f;
                totalCost += f * to[e][2];
            }
        }

        return totalCost;
    }
}
